DO $$ DECLARE definition text;fixed text; BEGIN SELECT pg_get_functiondef('public.quality_checked_command(jsonb)'::regprocedure) INTO definition;fixed:=replace(definition,'RETURN public.quality_command(command);','IF act=''feedback'' THEN RETURN (public.quality_command(command) - ''payload'') || jsonb_build_object(''payload'',jsonb_build_object(''customerConfirmation'',p->>''customerConfirmation'')); END IF; RETURN public.quality_command(command);');IF fixed=definition THEN RAISE EXCEPTION 'Expected result expression was not found';END IF;EXECUTE fixed;END $$;